      "id": "P1",
      "expression": "1 <= n <= 300000",
      "description": "The number of cities is between 1 and 300,000, inclusive."
    },
    {
      "id": "P2",
      "expression": "0 <= m < n",
      "description": "The number of roads is between 0 and the number of cities minus 1, inclusive."
    },
