    },
    {
      "id": "Q2",
      "expression": "output[i] == length of the longest path in the merged region after event 2 xi yi",
      "description": "The output for each event of the second type is the length of the longest path in the merged region after merging the region containing city xi with the region containing city yi."
    }
  ],
